mapper.select:
SELECT 
FROM tb_mdm_configuration t
WHERE t.row_valid = 1

    AND t.id = #{id}


    AND t.code = #{code}


    AND t.name = #{name}


    AND t.name_local = #{nameLocal}


    AND t.variant_code = #{variantCode}


    AND t.source = #{source}


    AND t.external_ref_id = #{externalRefId}


    AND t.external_version = #{externalVersion}


    AND t.description = #{description}


    AND t.create_time = #{createTime}


    AND t.create_by = #{createBy}


    AND t.modify_time = #{modifyTime}


    AND t.modify_by = #{modifyBy}


    AND t.row_version = #{rowVersion}

ORDER BY t.id DESC

SELECT 
FROM tb_mdm_configuration t
WHERE t.row_valid = 1

    AND t.code = #{code}


    AND t.name LIKE #{name}


    AND t.variant_code = #{variantCode}


    and date_format(t.create_time,'%Y%m%d') >= date_format(#{beginTime},'%Y%m%d')


    and date_format(t.create_time,'%Y%m%d') <= date_format(#{endTime},'%Y%m%d')

ORDER BY t.id DESC

SELECT COUNT(*)
FROM tb_mdm_configuration t
WHERE t.row_valid = 1

    AND t.code = #{code}


    AND t.variant_code = #{variantCode}

