WHERE c.row_valid = 1 AND c.code IN
#{code}

SELECT 

WHERE c.row_valid = 1

    AND c.code = #{code}


    AND c.name LIKE #{name}


    AND c.variant_code = #{variantCode}


    AND v.model_code = #{modelCode}


    AND m.car_line_code = #{carLineCode}


    AND m.platform_code = #{platformCode}


    AND cl.brand_code = #{brandCode}


    and date_format(c.create_time,'%Y%m%d') >= date_format(#{beginTime},'%Y%m%d')


    and date_format(c.create_time,'%Y%m%d') <= date_format(#{endTime},'%Y%m%d')

ORDER BY c.id DESC

SELECT COUNT(*)
FROM tb_mdm_configuration c
LEFT JOIN tb_mdm_variant v ON v.code = c.variant_code AND v.row_valid = 1
LEFT JOIN tb_mdm_model m ON m.code = v.model_code AND m.row_valid = 1
LEFT JOIN tb_mdm_car_line cl ON cl.code = m.car_line_code AND cl.row_valid = 1
WHERE c.row_valid = 1

    AND c.code = #{code}


    AND c.name LIKE #{name}


    AND c.variant_code = #{variantCode}


    AND v.model_code = #{modelCode}


    AND m.car_line_code = #{carLineCode}


    AND m.platform_code = #{platformCode}


    AND cl.brand_code = #{brandCode}


    and date_format(c.create_time,'%Y%m%d') >= date_format(#{beginTime},'%Y%m%d')


    and date_format(c.create_time,'%Y%m%d') <= date_format(#{endTime},'%Y%m%d')
